export function drawBall(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number) {
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, 2 * Math.PI);
  ctx.fill();
}

export function drawBricks(ctx: CanvasRenderingContext2D, bricks: Array<{ x: number; y: number; width: number; height: number; color: string }>) {
  bricks.forEach((brick) => {
    ctx.fillStyle = brick.color;
    ctx.fillRect(brick.x, brick.y, brick.width, brick.height);
  });
}

export function drawLives(ctx: CanvasRenderingContext2D, x: number, y: number, size: number, lives: number) {
  ctx.fillStyle = 'white';
  for (let i = 0; i < lives; i++) {
    const cx = x + i * (size + 2);
    ctx.fillRect(cx, y, size, size);
  }
